'use strict';
const DATA=JSON.parse(document.getElementById('directory-data').textContent),P=DATA.pandals;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',location:'<circle cx="12" cy="12" r="6"/><path d="M12 2v4m0 12v4M2 12h4m12 0h4"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v6a3 3 0 0 0 3 3h6a3 3 0 0 0 0-6h-3a3 3 0 0 1 0-6h6"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 2-1 3 2 3 3-1 2 3 3-1 1-3 3-1 2-3-2-2 1-3-2-3-3 1-2-3z"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',instagram:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17.5 6.5h.01"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0z"/><circle cx="12" cy="10" r="2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',share:'<circle cx="5" cy="12" r="3"/><circle cx="19" cy="5" r="3"/><circle cx="19" cy="19" r="3"/><path d="m8 10 8-4m-8 8 8 4"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.pin}</svg>`;
function icons(){document.querySelectorAll('i[data-icon]').forEach(e=>e.outerHTML=icon(e.dataset.icon))}icons();
let storageOK=true;function read(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{storageOK=false;return f}}function write(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{storageOK=false;toast('Changes work this visit; this browser cannot save them permanently.')}}
let saved=new Set(read('jnp26_saved',[])),visited=new Set(read('jnp26_visited',[])),route=read('jnp26_route',[]).filter(id=>P.some(p=>p.id===id)),mode='walking';
let filter='all',limit=12,locationPoint=null,viewCompact=read('jnp26_compact',false),deferredInstall=null;
if(read('jnp26_dark',false))document.body.classList.add('dark');
const faq=[['How do I find pandals in my area?','Type an area, pandal or landmark in search, or select a neighbourhood from the area menu. Use Mahakali Darshan or Special themes to narrow the results.'],['How does Nearby work?','Choose an area without sharing location, or tap Nearby and allow your browser to use your location. Where exact pandal coordinates are unavailable, results show approximate straight-line distance to the area centre from the source guide. This is not walking distance or an exact pandal pin. Some areas have no coordinate estimate.'],['How do I plan a Darshan route?','Add pandals from their details to My route. Reorder your stops, choose walking or driving, then open Google Maps. Routes with more than four stops open in smaller groups to support mobile navigation. Google Maps provides road directions and travel estimates.'],['Are Aarti and crowd details live?','This guide is a snapshot of public information checked on 30 September 2026. Listed dates and times may change. Aarti filters show published schedules, not a claim that an event is happening now. Live crowd monitoring is not connected. Verify with the respective samiti.'],['Can I install it as an app?','After the site launches over HTTPS, use Install app in Settings on supported Android and desktop browsers. On iPhone, open it in Safari, tap Share, then Add to Home Screen. Offline access becomes available after an online visit. Installation is not available in a downloaded file preview.'],['Will my saved pandals stay saved?','Saved, visited and route lists are kept in your browser on this device when local storage is available. They do not sync across devices. Clearing browser data removes these lists. No account is needed.'],['How can I suggest a correction or get a website made?','Open Settings for Nitesh Patel’s WhatsApp, Instagram @_nitesh_visions and web development portfolio. You can open WhatsApp with the pandal name for a correction; nothing is sent until you send it yourself.']];
$('#faqlist').innerHTML=faq.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('');
const schema=document.createElement('script');schema.type='application/ld+json';schema.textContent=JSON.stringify({'@context':'https://schema.org','@type':'FAQPage',mainEntity:faq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});document.head.append(schema);
const areas=[...new Set(P.map(p=>p.area))].sort();$('#area').innerHTML+='<option disabled>────────────</option>'+areas.map(a=>`<option value="${esc(a)}">${esc(a)} (${P.filter(p=>p.area===a).length})</option>`).join('');
$('#total').textContent=P.length;$('#areascount').textContent=areas.length;$('#kalicount').textContent=P.filter(p=>p.category.includes('Mahakali')).length;
const known=s=>Boolean(s)&&!/to be|awaiting|pending|announc/i.test(s);
const display=s=>known(s)?esc(s):'Awaiting update';
function mapQuery(p){return p.address||`${p.landmark||p.name}, ${p.area}, Jabalpur, Madhya Pradesh`}
function mapLink(p){return p.maps||'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(mapQuery(p))}
function distance(p){let coord=Number.isFinite(p.lat)&&Number.isFinite(p.lng)?[p.lat,p.lng]:DATA.centroids[p.area];if(!locationPoint||!coord)return null;let r=x=>x*Math.PI/180,dlat=r(coord[0]-locationPoint[0]),dlng=r(coord[1]-locationPoint[1]);return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(r(locationPoint[0]))*Math.cos(r(coord[0]))*Math.sin(dlng/2)**2))}
function dateSort(s){let m=String(s).match(/(\d{1,2})\s+Oct/i);return m?Number(m[1]):99}
function mainView(){return !$('#search').value.trim()&&!$('#area').value&&filter==='all'&&!locationPoint} function matches(){let q=$('#search').value.trim().toLowerCase(),area=$('#area').value;let list=P.filter(p=>(!area||p.area===area)&&(!q||[p.name,p.area,p.landmark,p.address,p.theme,...(p.tags||[])].join(' ').toLowerCase().includes(q))&&(filter==='all'||filter==='mahakali'&&p.category.includes('Mahakali')||filter==='themes'&&p.theme||filter==='aarti'&&known(p.aartiTime)||filter==='saved'&&saved.has(p.id)||filter==='visited'&&visited.has(p.id)));
if(mainView())list=list.filter(p=>DATA.mainPandalIds.includes(p.id));let sort=$('#sort').value;list.sort((a,b)=>sort==='az'?a.name.localeCompare(b.name):sort==='arrival'?dateSort(a.aagmanDate)-dateSort(b.aagmanDate)||a.name.localeCompare(b.name):sort==='nearby'?(distance(a)??Infinity)-(distance(b)??Infinity)||a.name.localeCompare(b.name):Number(Boolean(b.photo))-Number(Boolean(a.photo))||Number(Boolean(b.featured))-Number(Boolean(a.featured))||a.name.localeCompare(b.name));return list}
function card(p){let dist=distance(p);return `<article class="card ${viewCompact?'compact':''}" id="pandal-${esc(p.id)}"><div class="cardvisual">${p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.name)} in ${esc(p.area)}, Jabalpur" loading="lazy">${p.photoYear?`<small class="imagecaption">Navratri ${esc(p.photoYear)} · archive photo</small>`:''}`:`<div class="festivalart" role="img" aria-label="Jabalpur Navratri Darshan 2026 festival illustration"><img src="navratri-art.webp" alt="" loading="lazy"><div class="festivalart-title"><span>जय माता दी</span><strong>Jabalpur Navratri<br>Darshan <b>2026</b></strong><small>Festival illustration · photo pending</small></div></div>`}<span class="badge">${esc(p.category)}</span><button class="savebutton" data-save="${esc(p.id)}" aria-label="${saved.has(p.id)?'Unsave':'Save'} ${esc(p.name)}" aria-pressed="${saved.has(p.id)}">${icon(saved.has(p.id)?'check':'bookmark')}</button></div><div class="cardbody"><div class="area">${esc(p.area)}${dist!==null?` · ≈ ${dist.toFixed(1)} km${Number.isFinite(p.lat)?'':' to area'}`:''}</div><h3><a href="pandals/${esc(p.id)}/index.html">${esc(p.name)}</a></h3><p class="address">${icon('pin')}<span>${esc(p.landmark||p.address||'Address awaiting update')}</span></p>${p.theme?`<div class="theme">${esc(p.theme)}</div>`:''}<div class="timings"><div><span>AAGMAN</span><b>${display(p.aagmanDate)}</b></div><div><span>MAHA AARTI</span><b>${display(p.aartiTime)}</b></div></div></div><div class="cardactions"><a class="btn primary" href="${esc(mapLink(p))}" target="_blank" rel="noopener noreferrer">${icon('pin')} Directions</a><a class="btn" href="pandals/${esc(p.id)}/index.html">View pandal</a><button data-visit="${esc(p.id)}" aria-label="${visited.has(p.id)?'Unmark visited':'Mark visited'} ${esc(p.name)}" aria-pressed="${visited.has(p.id)}">${icon(visited.has(p.id)?'check':'clock')}</button></div></article>`}
function render(){let list=matches();$('#directory-title').textContent=mainView()?'Main pandals of Jabalpur':'Find your Darshan';$('#grid').innerHTML=list.length?list.slice(0,limit).map(card).join(''):`<div class="empty"><h3>No pandals match these filters</h3><p>Try another area or clear your search.</p><button data-reset>Reset filters</button></div>`;$('#resultcount').textContent=`${list.length} pandals${$('#area').value?' in '+$('#area').value:' across Jabalpur'} · ${Math.min(limit,list.length)} shown`;$('#more').classList.toggle('hidden',limit>=list.length);$('#more').textContent=`Show more pandals (${Math.max(0,list.length-limit)} remaining)`;$('#navcount').textContent=route.length;$('#journeycount').textContent=`${saved.size} saved · ${visited.size} visited · ${route.length} route stops`;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('selected',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)})}
function reset(){filter='all';limit=12;locationPoint=null;$('#area').value='';$('#search').value='';$('#sort').value='featured';render()}
$('#search').addEventListener('input',()=>{limit=117;render()});$('#area').addEventListener('change',()=>{limit=117;render()});$('#sort').addEventListener('change',()=>{if($('#sort').value==='nearby'&&!locationPoint){near();return}render()});$('#reset').onclick=reset;$('#more').onclick=()=>{limit+=12;render()};
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4500)}
function open(title,body){$('#modaltitle').textContent=title;$('#modalbody').innerHTML=body;icons();if(!$('#modal').open)$('#modal').showModal()}
$('#closemodal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function routePersist(){write('jnp26_route',route);render()}
function routePanel(){open('My Darshan route',`<p>Add pandals using their Details button. Stops open in the order below; reorder them to suit your evening.</p><div class="modebar"><button data-mode="walking" class="${mode==='walking'?'selected':''}">Walking</button><button data-mode="driving" class="${mode==='driving'?'selected':''}">Driving</button></div>${route.length?route.map((id,i)=>{let p=P.find(p=>p.id===id);return `<div class="routeitem"><span class="routenumber">${i+1}</span><div class="itemname">${esc(p.name)}<small>${esc(p.area)}</small></div><button data-up="${esc(id)}" ${i===0?'disabled':''} aria-label="Move ${esc(p.name)} earlier">↑</button><button data-down="${esc(id)}" ${i===route.length-1?'disabled':''} aria-label="Move ${esc(p.name)} later">↓</button><button data-remove="${esc(id)}" aria-label="Remove ${esc(p.name)}">${icon('close')}</button></div>`}).join(''):`<div class="empty">Your route is empty. Explore pandals and add your first stop.</div>`}<h3>Navigation</h3><div class="contactlinks" id="maproutes">${routeLinks()}</div><p class="sub">Google Maps chooses the road route. Stops use the source addresses; check the destination pin before setting off. Routes with more than four stops are split into sections.</p><div class="contactlinks"><button data-route-share>${icon('share')} Share route</button><button data-add-saved>Add saved pandals</button><button data-circuit="Garha">Garha circuit</button><button data-circuit="Ranjhi">Ranjhi circuit</button><button data-circuit="Sadar">Sadar circuit</button></div>`)}
function routeLinks(){if(!route.length)return 'Add at least one pandal to enable navigation.';let links=[];for(let i=0;i<route.length;i+=3){let group=route.slice(i,i+4).map(id=>P.find(p=>p.id===id));if(group.length===1&&i>0)continue;let params=new URLSearchParams({api:'1',destination:mapQuery(group[group.length-1]),travelmode:mode});if(i>0)params.set('origin',mapQuery(group[0]));if(group.length>1)params.set('waypoints',group.slice(i>0?1:0,-1).map(mapQuery).join('|'));links.push(`<a class="btn primary" href="https://www.google.com/maps/dir/?${esc(params.toString())}" target="_blank" rel="noopener noreferrer">${icon('route')} ${route.length<=4?'Open Google Maps':`Open stops ${i+1}–${i+group.length}`}</a>`)}return links.join('')}
function detail(id){let p=P.find(p=>p.id===id);if(!p)return;open(p.name,`${p.photo?`<img class="detailphoto" src="${esc(p.photo)}" alt="${esc(p.name)}">`:''}<p class="area">${esc(p.area)} · ${esc(p.category)}</p>${p.theme?`<p>${esc(p.theme)}</p>`:''}<dl class="detaildl"><dt>Address</dt><dd>${esc(p.address||p.landmark||'Awaiting update')}</dd><dt>Aagman</dt><dd>${display(p.aagmanDate)}</dd><dt>Maha Aarti</dt><dd>${display(p.aartiTime)}</dd><dt>Crowd</dt><dd>Live updates unavailable</dd></dl><div class="contactlinks"><a class="btn primary" href="${esc(mapLink(p))}" target="_blank" rel="noopener noreferrer">${icon('pin')} Get directions</a><button data-add="${esc(id)}">${route.includes(id)?'Added to route':'Add to route'}</button>${p.instagram?`<a class="btn" href="${esc(p.instagram)}" target="_blank" rel="noopener noreferrer">${icon('instagram')} Samiti Instagram</a>`:''}<button data-share="${esc(id)}">${icon('share')} Share pandal</button></div><p class="sub">Public directory snapshot · 30 September 2026. Verify the schedule and map pin with the samiti.</p><a class="btn" href="https://wa.me/917974823298?text=${encodeURIComponent('Pandal correction: '+p.name+' ('+p.area+')\nDetails: ')}" target="_blank" rel="noopener noreferrer">Suggest a correction</a>`)}
function settings(){open('Settings & creator',`<div class="settingrow"><div><strong>Evening mode</strong><small>A darker display for night-time Darshan.</small></div><button data-dark>${document.body.classList.contains('dark')?'Use light mode':'Use dark mode'}</button></div><div class="settingrow"><div><strong>Compact pandal cards</strong><small>Smaller image areas, same useful details.</small></div><button data-compact>${viewCompact?'Turn off':'Turn on'}</button></div><div class="settingrow"><div><strong>Install the guide</strong><small>Keep Jabalpur Darshan on your home screen.</small></div><button data-install>Install app</button></div><h3>Created by Nitesh Patel</h3><p>For pandal corrections, collaborations, or a website for your business, connect with Nitesh.</p><div class="contactlinks"><a class="btn primary" href="https://wa.me/917974823298?text=${encodeURIComponent('Hi Nitesh, I came from Jabalpur Navratri Pandals.')}" target="_blank" rel="noopener noreferrer">WhatsApp 7974823298</a><a class="btn" href="tel:+917974823298">Call Nitesh</a><a class="btn" href="https://www.instagram.com/_nitesh_visions/" target="_blank" rel="noopener noreferrer">Instagram @_nitesh_visions</a></div><h3>Need a website of your own?</h3><p>Explore Nitesh’s work and discuss a website for your shop, business, organisation or personal brand.</p><a class="btn" href="https://niteshpatel-webdev.vercel.app/" target="_blank" rel="noopener noreferrer">Visit Nitesh’s portfolio</a><h3>Your data</h3><p>Saved, visited and route lists stay in this browser. Location is requested only when you tap Nearby. It is used for distance estimates here and is not stored. Map links open Google Maps; WhatsApp and Instagram open only when you choose their links.</p><p class="sub">${storageOK?'Device saving is available.':'Persistent saving is unavailable in this browser; changes last for this visit.'} No sign-up required.</p><h3>Directory information</h3><p>117 source listings. Snapshot checked 30 September 2026. Some may describe the same samiti at nearby landmarks. Times, photos and exact coordinates are incomplete; pending information is labelled.</p>`)}
function near(){open('Find nearby pandals',`<p>Choose an area, or use your location to sort by approximate distance. Exact pandal coordinates are not available in the source dataset.</p><label for="neararea">Choose a Jabalpur area</label><select id="neararea">${areas.map(a=>`<option>${esc(a)}</option>`).join('')}</select><div class="contactlinks" style="margin-top:15px"><button data-area-near class="primary">Explore this area</button><button data-use-location>${icon('location')} Use my location</button></div><p class="sub">Location sorting uses the source’s area-centre estimates where available. Your location is used on this device only.</p>`)}
function locate(){if(!navigator.geolocation){toast('Location is unavailable. Please choose your area.');return}if(!window.isSecureContext){toast('Location needs HTTPS after launch. Choose your area for this preview.');return}toast('Checking your location…');navigator.geolocation.getCurrentPosition(pos=>{locationPoint=[pos.coords.latitude,pos.coords.longitude];$('#sort').value='nearby';$('#area').value='';$('#search').value='';filter='all';limit=117;$('#locationnotice').textContent='Nearby first · approximate straight-line distances to source area centres. Areas without coordinates appear last.';$('#modal').close();render();$('#directory').scrollIntoView();toast('Nearby areas sorted. Distances are estimates.');},err=>toast(err.code===1?'Location permission declined. Choose your area instead.':'Could not get your location. Choose your area instead.'),{timeout:12000,maximumAge:60000,enableHighAccuracy:false})}
async function share(text,url){try{if(navigator.share)await navigator.share({title:'Jabalpur Navratri Pandals',text,url});else if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text+'\n'+url);toast('Copied to clipboard.')}else open('Copy & share',`<p>Select and copy the details below.</p><textarea readonly style="width:100%;min-height:180px;font:inherit">${esc(text+'\n'+url)}</textarea>`)}catch(e){if(e.name!=='AbortError')toast('Sharing could not open. Please try again.')}}
async function install(){if(deferredInstall){await deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;return}open('Install Jabalpur Darshan',`<p>${location.protocol==='file:'?'You are viewing a downloaded preview. App installation becomes available when the website launches over HTTPS.':'If an automatic install prompt is unavailable, use your browser’s installation menu.'}</p><h3>Android & desktop</h3><p>In Chrome or Edge, open the browser menu and choose Install app or Add to Home screen.</p><h3>iPhone & iPad</h3><p>Open this website in Safari, tap Share, then Add to Home Screen.</p><p>The installed guide stores its directory offline after an online visit. External Maps, WhatsApp and Instagram links still need internet access.</p>`)}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});window.addEventListener('appinstalled',()=>toast('Darshan guide installed.'));
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.filter){filter=d.filter;limit=117;render()}else if(d.save){saved.has(d.save)?saved.delete(d.save):saved.add(d.save);write('jnp26_saved',[...saved]);render()}else if(d.visit){visited.has(d.visit)?visited.delete(d.visit):visited.add(d.visit);write('jnp26_visited',[...visited]);render()}else if(d.detail)detail(d.detail);else if(d.open==='routes')routePanel();else if(d.open==='settings')settings();else if('near'in d)near();else if('install'in d)install();else if('dark'in d){document.body.classList.toggle('dark');write('jnp26_dark',document.body.classList.contains('dark'));settings()}else if('compact'in d){viewCompact=!viewCompact;write('jnp26_compact',viewCompact);render();settings()}else if(d.add){if(!route.includes(d.add)){route.push(d.add);routePersist();toast('Added to your route.')}detail(d.add)}else if(d.remove){route=route.filter(id=>id!==d.remove);routePersist();routePanel()}else if(d.up||d.down){let id=d.up||d.down,i=route.indexOf(id),j=i+(d.up?-1:1);if(j>=0&&j<route.length)[route[i],route[j]]=[route[j],route[i]];routePersist();routePanel()}else if(d.mode){mode=d.mode;routePanel()}else if('addSaved'in d){route=[...new Set([...route,...saved])];routePersist();routePanel()}else if(d.circuit){route=P.filter(p=>p.area===d.circuit).sort((a,b)=>Number(b.featured)-Number(a.featured)).slice(0,4).map(p=>p.id);routePersist();routePanel()}else if('areaNear'in d){$('#area').value=$('#neararea').value;filter='all';limit=117;$('#sort').value='featured';$('#search').value='';$('#modal').close();render();$('#directory').scrollIntoView()}else if('useLocation'in d)locate();else if('reset'in d)reset();else if(d.share){let p=P.find(p=>p.id===d.share);share(`${p.name}\n${p.address}\nAagman: ${p.aagmanDate}\nAarti: ${p.aartiTime}\nMaps: ${mapLink(p)}`,location.protocol==='file:'?mapLink(p):location.origin+location.pathname+'#p='+encodeURIComponent(p.id))}else if('routeShare'in d){if(!route.length){toast('Add a stop first.');return}share('My Jabalpur Darshan route\n'+route.map((id,i)=>`${i+1}. ${P.find(p=>p.id===id).name}\n${mapLink(P.find(p=>p.id===id))}`).join('\n'),location.protocol==='file:'?'https://www.instagram.com/_nitesh_visions/':location.origin+location.pathname+'#route='+encodeURIComponent(route.join(',')))}});
function hashOpen(){let hash=location.hash;if(hash.startsWith('#p='))detail(decodeURIComponent(hash.slice(3)));if(hash.startsWith('#route=')){let ids=decodeURIComponent(hash.slice(7)).split(',').filter(id=>P.some(p=>p.id===id));if(ids.length){route=ids;routePersist();routePanel()}}}render();hashOpen();window.addEventListener('hashchange',hashOpen);
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});

document.querySelectorAll('.mobile-menu a').forEach(a=>a.addEventListener('click',()=>a.closest('details').open=false));
